              "text": "Jul. 2022: Congratulations to Dr. Jinhyuk Lee, who joined Google (Mountain View, CA) as a research scientist. Dr. Lee joined the NLP team at Google Research that created BERT and Transformer, working alongside Jeff Dean. Congratulations!",
              "links": []
